-- =============================================================================
-- NON-DESTRUCTIVE POST-SEED INTEGRITY & VOLUME VERIFICATION
-- =============================================================================

DO $$
DECLARE
    v_users_count INT;
    v_drivers_count INT;
    v_vehicles_count INT;
    v_seats_count INT;
    v_routes_count INT;
    v_trips_count INT;
    v_bookings_count INT;
    v_dup_seats_count INT;
    v_gps_m09 INT;
    v_gps_m10 INT;
    v_gps_m11 INT;
    v_gps_def INT;
    v_failed_assertions INT := 0;
BEGIN
    RAISE NOTICE '--------------------------------------------------------------------';
    RAISE NOTICE 'STARTING EXTENDED SEED VERIFICATION ASSERTIONS';
    RAISE NOTICE '--------------------------------------------------------------------';

    -- 1. Users count assertion (Expect >= 53)
    SELECT COUNT(*) INTO v_users_count FROM users;
    IF v_users_count >= 53 THEN
        RAISE NOTICE '[PASS] Users count assertion: % users found (minimum 53)', v_users_count;
    ELSE
        RAISE WARNING '[FAIL] Users count below minimum: % found', v_users_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 2. Drivers count assertion (Expect >= 16)
    SELECT COUNT(*) INTO v_drivers_count FROM drivers;
    IF v_drivers_count >= 16 THEN
        RAISE NOTICE '[PASS] Drivers count assertion: % drivers found (minimum 16)', v_drivers_count;
    ELSE
        RAISE WARNING '[FAIL] Drivers count below minimum: % found', v_drivers_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 3. Vehicles count assertion (Expect >= 11)
    SELECT COUNT(*) INTO v_vehicles_count FROM vehicles;
    IF v_vehicles_count >= 11 THEN
        RAISE NOTICE '[PASS] Vehicles count assertion: % vehicles found (minimum 11)', v_vehicles_count;
    ELSE
        RAISE WARNING '[FAIL] Vehicles count below minimum: % found', v_vehicles_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 4. Seats count assertion (Expect >= 390)
    SELECT COUNT(*) INTO v_seats_count FROM seats;
    IF v_seats_count >= 390 THEN
        RAISE NOTICE '[PASS] Seats count assertion: % seats found (minimum 390)', v_seats_count;
    ELSE
        RAISE WARNING '[FAIL] Seats count below minimum: % found', v_seats_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 5. Routes count assertion (Expect >= 11)
    SELECT COUNT(*) INTO v_routes_count FROM routes;
    IF v_routes_count >= 11 THEN
        RAISE NOTICE '[PASS] Routes count assertion: % routes found (minimum 11)', v_routes_count;
    ELSE
        RAISE WARNING '[FAIL] Routes count below minimum: % found', v_routes_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 6. Trips count assertion (Expect >= 61)
    SELECT COUNT(*) INTO v_trips_count FROM trips;
    IF v_trips_count >= 61 THEN
        RAISE NOTICE '[PASS] Trips count assertion: % trips found (minimum 61)', v_trips_count;
    ELSE
        RAISE WARNING '[FAIL] Trips count below minimum: % found', v_trips_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 7. Bookings count assertion (Expect >= 181)
    SELECT COUNT(*) INTO v_bookings_count FROM bookings;
    IF v_bookings_count >= 181 THEN
        RAISE NOTICE '[PASS] Bookings count assertion: % bookings found (minimum 181)', v_bookings_count;
    ELSE
        RAISE WARNING '[FAIL] Bookings count below minimum: % found', v_bookings_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 8. Anti-Double-Booking Concurrency Invariant Check
    SELECT COUNT(*) INTO v_dup_seats_count
    FROM (
        SELECT trip_id, seat_id, COUNT(*)
        FROM booking_seats
        WHERE status IN ('PENDING', 'CONFIRMED')
        GROUP BY trip_id, seat_id
        HAVING COUNT(*) > 1
    ) dup;

    IF v_dup_seats_count = 0 THEN
        RAISE NOTICE '[PASS] Seat Concurrency: Zero duplicate active seat allocations detected across all trips';
    ELSE
        RAISE WARNING '[FAIL] CRITICAL: % duplicate seat allocations detected!', v_dup_seats_count;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 9. GPS Partition Coverage
    SELECT COUNT(*) INTO v_gps_m09 FROM vehicle_location_history_y2026m09;
    SELECT COUNT(*) INTO v_gps_m10 FROM vehicle_location_history_y2026m10;
    SELECT COUNT(*) INTO v_gps_m11 FROM vehicle_location_history_y2026m11;
    SELECT COUNT(*) INTO v_gps_def FROM vehicle_location_history_default;

    IF v_gps_m09 > 0 AND v_gps_m10 > 0 AND v_gps_m11 > 0 AND v_gps_def > 0 THEN
        RAISE NOTICE '[PASS] GPS Partitions Populated: Sep-2026=%, Oct-2026=%, Nov-2026=%, Default=%',
            v_gps_m09, v_gps_m10, v_gps_m11, v_gps_def;
    ELSE
        RAISE WARNING '[FAIL] GPS Partitions missing records: Sep=%, Oct=%, Nov=%, Def=%',
            v_gps_m09, v_gps_m10, v_gps_m11, v_gps_def;
        v_failed_assertions := v_failed_assertions + 1;
    END IF;

    -- 10. Final validation check
    IF v_failed_assertions > 0 THEN
        RAISE EXCEPTION 'CRITICAL: Extended seed post-verification encountered % failed assertions. Transaction aborted.', v_failed_assertions;
    ELSE
        RAISE NOTICE '--------------------------------------------------------------------';
        RAISE NOTICE 'ALL EXTENDED SEED INTEGRITY ASSERTIONS PASSED SUCCESSFULLY!';
        RAISE NOTICE '--------------------------------------------------------------------';
    END IF;
END $$;

COMMIT;
